class Solution {
public:
    std::vector<int> smallestSubarrays(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> ans(n, 1);
        std::vector<int> last_pos(30, -1);

        for (int i = n - 1; i >= 0; i--) {
            for (int b = 0; b < 30; b++) {
                if ((nums[i] >> b) & 1) {
                    last_pos[b] = i;
                }
            }
            int furthest = i;
            for (int b = 0; b < 30; b++) {
                if (last_pos[b] != -1) {
                    furthest = std::max(furthest, last_pos[b]);
                }
            }
            ans[i] = furthest - i + 1;
        }
        return ans;
    }
};

class Solution {
    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        int[] lastPos = new int[30];
        java.util.Arrays.fill(lastPos, -1);

        for (int i = n - 1; i >= 0; i--) {
            for (int b = 0; b < 30; b++) {
                if (((nums[i] >> b) & 1) == 1) {
                    lastPos[b] = i;
                }
            }
            int furthest = i;
            for (int b = 0; b < 30; b++) {
                if (lastPos[b] != -1) {
                    furthest = Math.max(furthest, lastPos[b]);
                }
            }
            ans[i] = furthest - i + 1;
        }
        return ans;
    }
}

